and ( d.product_code like concat('%', #{code}, '%') or exists ( select 1 from product_sku s where s.product_id = d.id and s.sku_code like concat('%', #{code}, '%') ) )
and d.name like concat('%', #{name}, '%')
and d.category_id = #{categoryId}
and d.status = #{status}
order by d.create_time desc

